import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test user registration functionality with valid email formats.
 *
 * This test validates that the user registration API works correctly with
 * properly formatted email addresses. Since the API contract enforces email
 * format validation at the type level (string & tags.Format<"email">), this
 * test focuses on ensuring the registration process completes successfully with
 * valid email addresses.
 *
 * Test scenarios:
 *
 * 1. Registration with randomly generated valid email addresses
 * 2. Verification of successful user creation and authentication
 * 3. Validation of response data structure and token generation
 */
export async function test_api_user_registration_invalid_email_format(
  connection: api.IConnection,
) {
  // Generate multiple valid email addresses for testing
  const validEmails = ArrayUtil.repeat(5, () =>
    typia.random<string & tags.Format<"email">>(),
  );

  // Test registration with each valid email
  for (const validEmail of validEmails) {
    const user = await api.functional.auth.user.join(connection, {
      body: {
        email: validEmail,
        password: RandomGenerator.alphaNumeric(12),
      } satisfies ITodoListUser.ICreate,
    });

    typia.assert(user);
    TestValidator.equals(
      "registered user email should match input",
      user.email,
      validEmail,
    );
    TestValidator.predicate(
      "user should have valid authentication token",
      typeof user.token.access === "string" && user.token.access.length > 0,
    );
    TestValidator.predicate(
      "user should have valid refresh token",
      typeof user.token.refresh === "string" && user.token.refresh.length > 0,
    );
    TestValidator.predicate(
      "user should have token expiration dates",
      typeof user.token.expired_at === "string" &&
        typeof user.token.refreshable_until === "string",
    );
    TestValidator.predicate(
      "user should have active status by default",
      user.status === "active",
    );
    TestValidator.predicate(
      "user should have creation timestamp",
      typeof user.created_at === "string" && user.created_at.length > 0,
    );
    TestValidator.predicate(
      "user should have update timestamp",
      typeof user.updated_at === "string" && user.updated_at.length > 0,
    );
  }

  // Test duplicate email registration should fail
  const duplicateEmail = typia.random<string & tags.Format<"email">>();

  // First registration should succeed
  const firstUser = await api.functional.auth.user.join(connection, {
    body: {
      email: duplicateEmail,
      password: RandomGenerator.alphaNumeric(12),
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(firstUser);

  // Second registration with same email should fail
  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: {
          email: duplicateEmail,
          password: RandomGenerator.alphaNumeric(12),
        } satisfies ITodoListUser.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test user registration with weak password that doesn't meet security
 * requirements. Attempt to register with passwords that are too short, lack
 * character diversity, or use common patterns. Verify that the system enforces
 * password strength policies and rejects weak passwords with appropriate
 * validation errors.
 */
export async function test_api_user_registration_weak_password(
  connection: api.IConnection,
) {
  // Define weak password test cases covering various failure scenarios
  const weakPasswords = [
    "123", // Too short (minimum length violation)
    "password", // Common dictionary word
    "12345678", // Only numeric characters
    "abcdefgh", // Only alphabetic characters
    "a", // Single character (extreme shortness)
    "", // Empty password
    "         ", // Only whitespace characters
    "abc123", // Short alphanumeric pattern
    "qwerty", // Keyboard sequence pattern
    "11111111", // Repeated single digit
    "aaaaaaaa", // Repeated single character
  ] as const;

  // Test each weak password scenario - all should be rejected
  for (const weakPassword of weakPasswords) {
    const testEmail = typia.random<string & tags.Format<"email">>();

    await TestValidator.error(
      `password "${weakPassword}" should be rejected as weak`,
      async () => {
        await api.functional.auth.user.join(connection, {
          body: {
            email: testEmail,
            password: weakPassword,
          } satisfies ITodoListUser.ICreate,
        });
      },
    );
  }

  // Test a strong password to ensure valid registration works correctly
  // Strong password includes uppercase, lowercase, numbers, and special characters
  const strongPassword = "StrongPass123!@#";
  const validEmail = typia.random<string & tags.Format<"email">>();

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: validEmail,
      password: strongPassword,
    } satisfies ITodoListUser.ICreate,
  });

  typia.assert(user);
  TestValidator.equals(
    "registered user email matches input email",
    user.email,
    validEmail,
  );
  TestValidator.predicate(
    "user should have valid non-empty authentication tokens",
    user.token.access.length > 0 && user.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "user account should be created with active status",
    user.status === "active",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test successful user authentication workflow.
 *
 * This test validates the complete user authentication process by first
 * registering a new user account and then using the same credentials to log in.
 * It verifies that the system properly authenticates the user, validates
 * credentials against stored hashes, generates new authentication tokens, and
 * returns complete user identity information. The test also validates session
 * context recording including IP, href, and referrer tracking.
 */
export async function test_api_user_login_success(connection: api.IConnection) {
  // Step 1: Create user account for login testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = RandomGenerator.alphaNumeric(12);

  const registeredUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(registeredUser);

  // Step 2: Login with the same credentials
  const loginResponse = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      ip: "192.168.1.100",
      href: "https://example.com/auth/login",
      referrer: "https://example.com/dashboard",
    } satisfies ITodoListUser.ILogin,
  });
  typia.assert(loginResponse);

  // Step 3: Validate user identity information
  TestValidator.equals(
    "user ID should match registered user",
    loginResponse.id,
    registeredUser.id,
  );
  TestValidator.equals(
    "user email should match registered email",
    loginResponse.email,
    registeredUser.email,
  );
  TestValidator.equals(
    "user status should be active",
    loginResponse.status,
    "active",
  );

  // Step 4: Validate authentication tokens
  TestValidator.predicate(
    "access token should be present",
    loginResponse.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be present",
    loginResponse.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "token expiration should be valid date",
    new Date(loginResponse.token.expired_at) > new Date(),
  );
  TestValidator.predicate(
    "refreshable until should be valid date",
    new Date(loginResponse.token.refreshable_until) > new Date(),
  );

  // Step 5: Validate token structure
  typia.assert<IAuthorizationToken>(loginResponse.token);

  // Step 6: Validate session context recording (indirectly through successful login)
  TestValidator.predicate(
    "user should have creation timestamp",
    loginResponse.created_at.length > 0,
  );
  TestValidator.predicate(
    "user should have update timestamp",
    loginResponse.updated_at.length > 0,
  );
  TestValidator.predicate(
    "deleted_at should be undefined for active user",
    loginResponse.deleted_at === undefined,
  );
}

