  TestValidator.equals(
    "user ID matches created user",
    loginResponse.id,
    createdUser.id,
  );
  TestValidator.equals(
    "email matches login credentials",
    loginResponse.email,
    userEmail,
  );
  TestValidator.equals("user status is active", loginResponse.status, "active");

